ref_dict.ell_brascamp_lieb:
\begin{theorem}[Ellipsoids and Brascamp--Lieb]\label{ell_brascamp_lieb}
Let $\mathcal{E}\subset\mathbb{R}^d$ be an ellipsoid and $\{w_1,\dots,w_d\}$ a basis of $\mathbb{R}^d$. Let $m\ge1$ and let $(\sigma_1,\dots,\sigma_m)$ a uniform cover of $[d]$ with weights $(p_1,\dots,p_m)$. Let $F_j=span\{w_k:k\in\sigma_j\}$ and $dim(F_j)=|\sigma_j|=d_j$ let $\{P_{F_j}\}$ be orthogonal projections onto subspaces $F_j$ with $\dim F_j=d_j$.
Then
\begin{equation}\label{main-ell}
\frac{c_{\mathrm{ell}}}{BL_2}\prod_j |P_{F_j}\mathcal{E}|^{p_j}\le|\mathcal{E}| \le C_{\mathrm{ell}}BL_2\prod_j |P_{F_j}\mathcal{E}|^{p_j},
\end{equation}
where
\begin{equation}\label{Cell}
C_{\mathrm{ell}}\;=\;\frac{\omega_d}{\prod_j \omega_{d_j}^{\,p_j}} \qquad\text{and }\qquad\text{} c_{\mathrm{ell}}=\frac{\omega_d}{d^{d/2}}\prod_{j=1}^{m}\Bigg(\frac{d_j^{d_j/2}}{\omega_{d_j}}\Bigg)^{p_j}
\end{equation}
and $\omega_m=|B_2^m|=\pi^{m/2}/\Gamma(\tfrac m2+1)$ is the volume of the unit Euclidean ball in $\mathbb{R}^m$. Moreover, the constant $C_{\mathrm{ell}}$ is optimal (it cannot be decreased uniformly for all ellipsoids).
\end{theorem}

ref_dict.reverse_loomis_zonoids:
\begin{theorem}\label{reverse_loomis_zonoids}
    Let $\mathbb{S}=(S,\sigma,v)$ a generalised $d$-hypersurface. There exists an orthonormal basis $\{w_i\}_{i=1}^{d}$ of $\mathbb{R}^d$ such that for any $1$-uniform cover $(\sigma_1,\dots, \sigma_m)$ of $[d]$ and $E_i = span\{w_j : j\in\sigma_i\}$ we have
     \begin{equation}
    \prod_{j=1}^m|P_{E_j}(\Pi(\mathbb{S}))|\le\frac{(\sqrt{d})^{d}}{\prod_{j=1}^m\sqrt{d_j!}}|\Pi(\mathbb{S})|.
     \end{equation}
\end{theorem}

ref_dict.cont_brascamp_lieb:
\begin{theorem}[Continuous Brascamp--Lieb on $S$]\label{cont_brascamp_lieb}
Let $S$ be a hypersurface equipped with a positive measure $\mu$.
Let $v:S\to\mathbb{R}^n$ be measurable with $v(x)\neq0$ for $\mu$‑almost every $x\in S$, and assume the normalization
\begin{equation}\label{eq:identity_assumption}
I_d= \int_S \frac{v(x)\otimes v(x)}{\|v(x)\|_2^2}\,d\mu(x).
\end{equation}
Define the unit directions $u(x):=v(x)/\|v(x)\|_2\in S^{n-1}$ and suppose we are given a measurable family
of non-negative functions ${f_x:\mathbb R\to[0,\infty)},{x\in S}$ that meets the usual technical integrability
conditions.

Then the following inequality holds:
\begin{equation}\label{eq:conclusion_S}
\int_{\mathbb R^n}\exp\Big(\int_S\log\bigl(f_x(\langle y,u(x)\rangle)\bigr)\,d\mu(x)\Big)\,dy
\le
\exp\Big(\int_S\log\Big(\int_{\mathbb R} f_x(t)\,dt\Big)\, d\mu(x)\Big).
\end{equation}
\end{theorem}

expanded_sketch:
To prove Corollary~\ref{cor:visaswedge} sharply (with explicit dependence on $d$ and the $k_i$), one uses two main ingredients.

(i) For the **upper bound**, one “first observe[s]” that the inequality used in Brazitikos--Carbery--MacIntyre (2023) (from Zhang, Theorem~3.1) “is in fact the reverse Santal\
{o} or Bourgain--Milman inequality,” giving “a lower bound for the product of the volume of a convex body and its polar.” Although the exact bound is open “for general convex bodies,” it “is known in the class of generalised zonoids, which is the case for $\Pi\mathbb{S}$.” Moreover, “the fact that the class of extremisers of this inequality are also extremisers for the affine-invariant Loomis--Whitney inequality allows us to obtain a sharp inequality for the upper bound.”

(ii) For the **lower bound**, “instead of using the axes of the John ellipsoid,” one uses “the axes of the Binet ellipsoid.” “Utilizing the isotropicity present there,” and “with the aid of a refinement of the Continuous Brascamp--Lieb inequality,” we use the following result.

\begin{theorem}[Continuous Brascamp--Lieb on $S$]\label{cont_brascamp_lieb}
Let $S$ be a hypersurface equipped with a positive measure $\mu$.
Let $v:S\to\mathbb{R}^n$ be measurable with $v(x)\neq0$ for $\mu$‑almost every $x\in S$, and assume the normalization
\begin{equation}\label{eq:identity_assumption}
I_d= \int_S \frac{v(x)\otimes v(x)}{\|v(x)\|_2^2}\,d\mu(x).
\end{equation}
Define the unit directions $u(x):=v(x)/\|v(x)\|_2\in S^{n-1}$ and suppose we are given a measurable family
of non-negative functions ${f_x:\mathbb R\to[0,\infty)},{x\in S}$ that meets the usual technical integrability
conditions.

Then the following inequality holds:
\begin{equation}\label{eq:conclusion_S}
\int_{\mathbb R^n}\exp\Big(\int_S\log\bigl(f_x(\langle y,u(x)\rangle)\bigr)\,d\mu(x)\Big)\,dy
\le
\exp\Big(\int_S\log\Big(\int_{\mathbb R} f_x(t)\,dt\Big)\, d\mu(x)\Big).
\end{equation}
\end{theorem}

With this refinement, we are able to obtain a sharp lower bound. This is “also connected with the reverse Loomis--Whitney inequalities”; in particular, they prove the following reverse Loomis--Whitney inequality for generalised $d$-hypersurfaces.

\begin{theorem}\label{reverse_loomis_zonoids}
    Let $\mathbb{S}=(S,\sigma,v)$ a generalised $d$-hypersurface. There exists an orthonormal basis $\{w_i\}_{i=1}^{d}$ of $\mathbb{R}^d$ such that for any $1$-uniform cover $(\sigma_1,\dots, \sigma_m)$ of $[d]$ and $E_i = span\{w_j : j\in\sigma_i\}$ we have
     \begin{equation}
    \prod_{j=1}^m|P_{E_j}(\Pi(\mathbb{S}))|\le\frac{(\sqrt{d})^{d}}{\prod_{j=1}^m\sqrt{d_j!}}|\Pi(\mathbb{S})|.
     \end{equation}
\end{theorem}

