\label{them profile}
		{\bf (The  case $\nu=0$)} There exists an absolute constant $\delta_{1}>0,$  sufficiently small, such that the following statements hold:

		(1) For \(a\in (1, 1+\delta_{1})\) The model
		\begin{align}\label{PJE}
		\begin{cases}
			\omega_{t} + u\omega_{x} = a\omega u_{x}+\nu\omega_{xx}, & t >0, \\ x \\in \\mathbb{T}, \\
			u_{xx} =\omega, & t >0, \\ x \\in \\mathbb{T}.
		\end{cases}
	\end{align}
		with $\nu=0$ develops a finite time singularity for some \(C^{\infty}\) initial data;

		(2) For all $a\in(1-\delta_{1},1+\delta_{1}),$ the model given by the system above admits a self-similar solution of the form
		\begin{align*}
			\omega(x,t) = \frac{1}{1 + c_{\omega,a}t}\omega_{a}(x),
		\end{align*}
		where $\omega_{a}$ is an odd profile and $c_{\omega,a}$ is the scaling parameter,  satisfying
		\begin{align}\label{the estimates}
			\|\omega_{a} +\sin (x)\|_{\mathcal{W}} \lesssim |1-a|, \quad |c_{\omega,a} - (1-a)|\leq \min\{C|1-a|^{2}, |1-a|\},
		\end{align}
		for some absolute constant $C > 0$. More precisely:
		\begin{itemize}
			\item for $1 < a < 1+\delta_{1}$, the scaling parameter satisfies $c_{\omega,a} < 0$, and the corresponding solution $\omega(x,t)$ blows up in finite time $T = -\frac{1}{c_{\omega,a}}$;
			\item for $a = 1$, the explicit steady state $\omega_{1} = -\sin (x)$ solves the system with $c_{\omega,a} = 0$;
			\item for $1-\delta_{1}<a<1$, one has $c_{\omega,a} > 0$, and the solution $\omega(x,t)$ exists globally with $O(t^{-1})$ decay rate as $t\to\infty$.
		\end{itemize}

